import { lazy } from 'react';
import { ArrowLeftRight as IcArrowLeftRight, BellRing as IcBellRing, BookmarkCheck as IcBookmarkCheck, Boxes as IcBoxes, Layers as IcLayers, PackageMinus as IcPackageMinus, ScanBarcode as IcScanBarcode } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Stock Control — hub page for the Inventory menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 7 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'StockControl'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const StockSummary = lazy(() => import('./StockSummary'));
const StockMovements = lazy(() => import('./StockMovements'));
const StockReservations = lazy(() => import('./StockReservations'));
const MaterialConsumption = lazy(() => import('./MaterialConsumption'));
const BatchTracking = lazy(() => import('./BatchTracking'));
const SerialTracking = lazy(() => import('./SerialTracking'));
const StockAlertsAndSuggestions = lazy(() => import('./StockAlertsAndSuggestions'));

export const TABS = [
  { id: 'summary', label: 'Stock Summary', icon: IcLayers, page: 'StockSummary', Component: StockSummary },
  { id: 'movements', label: 'Movements', icon: IcArrowLeftRight, page: 'StockMovements', Component: StockMovements },
  { id: 'reservations', label: 'Reservations', icon: IcBookmarkCheck, page: 'StockReservations', Component: StockReservations },
  { id: 'consumption', label: 'Consumption', icon: IcPackageMinus, page: 'MaterialConsumption', Component: MaterialConsumption },
  { id: 'batches', label: 'Batch Tracking', icon: IcBoxes, page: 'BatchTracking', Component: BatchTracking },
  { id: 'serials', label: 'Serial Tracking', icon: IcScanBarcode, page: 'SerialTracking', Component: SerialTracking },
  { id: 'alerts', label: 'Alerts', icon: IcBellRing, page: 'StockAlertsAndSuggestions', Component: StockAlertsAndSuggestions },
];

export default function StockControl({ setPage }) {
  return (
    <TabHub
      icon={IcBoxes}
      eyebrow="Inventory"
      title="Stock Control"
      subtitle="Balances, movements, reservations, consumption, traceability and alerts"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
